#include <string>
using namespace std;

class Solution {
public:
    char kthCharacter(long long k) {
        long long idx = k - 1;
        int shifts = __builtin_popcountll(idx);
        return 'a' + (shifts % 26);
    }
};

class Solution {
    public char kthCharacter(long k) {
        long idx = k - 1;
        int shifts = Long.bitCount(idx);
        return (char)('a' + (shifts % 26));
    }
}

var kthCharacter = function(k) {
    let idx = BigInt(k) - 1n;
    let shifts = 0;
    while (idx > 0n) {
        if (idx & 1n) shifts++;
        idx >>= 1n;
    }
    return String.fromCharCode(97 + (shifts % 26));
};
